<script setup lang="ts">
import { ref, computed, onMounted, onBeforeUnmount } from 'vue'
import { LayoutDashboard, Star, Clock3, Search, Plus, Upload, BookOpen, ArrowRight, MoreHorizontal, ChevronRight, FileText, PanelLeft, Download, Database, FolderPlus, Pencil, Trash2, Copy, ArrowLeft, Check, X, List, Grid2X2, SlidersHorizontal, ExternalLink, Paperclip } from 'lucide-vue-next'
import { MdEditor, MdPreview, MdCatalog } from 'md-editor-v3'
import 'md-editor-v3/lib/style.css'
import TreeItem from './TreeItem.vue'
import {api,send} from './api'

type Cat={id:number,name:string,parent_id:number|null,sort_order:number,is_system:boolean,path:string,note_count:number}
type Note={id:number,title:string,summary:string,content_md:string,category_id:number,status:string,difficulty:string,is_favorite:boolean,source_url:string,tags:string[],category_path:string,created_at:string,updated_at:string,last_viewed_at:string|null}
const cats=ref<Cat[]>([]), notes=ref<Note[]>([]), allNotes=ref<Note[]>([]), selected=ref<number|null>(null), expanded=ref(new Set<number>()), page=ref('overview'), current=ref<Note|null>(null), draft=ref<any>(null), dirty=ref(false), initialDraft=ref(''), search=ref(''), status=ref(''), recursive=ref(true), grid=ref(false), error=ref(''), showImport=ref(false), importItems=ref<any[]>([]), importPreview=ref<any[]>([]), createMissing=ref(false), duplicate=ref('skip'), attachments=ref<any[]>([]), sidebar=ref(true)
const searchCategory=ref(''), searchTag=ref(''), showDeleteCategory=ref(false), migrateTo=ref(''), availableTags=ref<string[]>([])
const copyMenu=ref<{x:number,y:number}|null>(null)
function selectionMenu(e:MouseEvent){if(!window.getSelection()?.toString())return;e.preventDefault();copyMenu.value={x:Math.min(e.clientX,window.innerWidth-110),y:Math.min(e.clientY,window.innerHeight-48)}}
function copySelection(){document.execCommand('copy');copyMenu.value=null}
const readerContent=computed(()=>{const n=current.value;if(!n)return '';const lines=n.content_md.split('\n');if(lines[0]?.replace(/^#\s+/, '').trim()===n.title && /^#\s+/.test(lines[0]))lines.shift();return lines.join('\n').replace(/^\s*\n/,'')})
const currentCategory=computed(()=>cats.value.find(c=>c.id===selected.value))
const roots=computed(()=>cats.value.filter(c=>c.parent_id===null))
const labels:Record<string,string>={not_started:'未开始',learning:'学习中',mastered:'已掌握',beginner:'入门',intermediate:'进阶',advanced:'高级'}
const pageTitle=computed(()=>({overview:'学习概览',favorites:'我的收藏',recent:'最近学习',search:'搜索结果',category:currentCategory.value?.name||'知识分类',read:current.value?.title||'阅读文档',edit:draft.value?.id?'编辑知识':'新建知识'} as Record<string,string>)[page.value])
const stats=computed(()=>({total:allNotes.value.length,not_started:allNotes.value.filter(n=>n.status==='not_started').length,learning:allNotes.value.filter(n=>n.status==='learning').length,mastered:allNotes.value.filter(n=>n.status==='mastered').length}))
const rootCount=(root:Cat)=>allNotes.value.filter(n=>n.category_path===root.path||n.category_path.startsWith(root.path+'/')).length
const recentNotes=computed(()=>[...allNotes.value].filter(n=>n.last_viewed_at).sort((a,b)=>(b.last_viewed_at||'').localeCompare(a.last_viewed_at||'')).slice(0,5))
const updatedNotes=computed(()=>[...allNotes.value].sort((a,b)=>b.updated_at.localeCompare(a.updated_at)).slice(0,5))
const date=(s:string|null)=>s?new Date(/(?:Z|[+-]\d\d:\d\d)$/.test(s)?s:s+'Z').toLocaleDateString('zh-CN',{year:'numeric',month:'short',day:'numeric'}):'—'
function fail(e:any){error.value=e.message||String(e);setTimeout(()=>error.value='',5000)}
async function refresh(){cats.value=await api('/categories');allNotes.value=await api('/notes');availableTags.value=await api('/tags');if(page.value==='category'||page.value==='favorites'||page.value==='recent'||page.value==='search') await loadNotes()}
async function loadNotes(){const p=new URLSearchParams();if(page.value==='category'&&selected.value){p.set('category_id',String(selected.value));p.set('recursive',String(recursive.value))}if(page.value==='favorites')p.set('favorite','true');if(page.value==='recent')p.set('recent','true');if(page.value==='search'){p.set('q',search.value);if(searchCategory.value){p.set('category_id',searchCategory.value);p.set('recursive','true')}if(searchTag.value)p.set('tag',searchTag.value)}if(status.value)p.set('status',status.value);notes.value=await api('/notes?'+p)}
function canLeave(){if(page.value==='edit'&&dirty.value&&!confirm('内容尚未保存，确定离开吗？'))return false;dirty.value=false;return true}
async function navigate(p:string,cat?:Cat){if(!canLeave())return;page.value=p;status.value='';if(cat){selected.value=cat.id;expanded.value.add(cat.id)}try{await loadNotes()}catch(e){fail(e)}}
function toggle(id:number){expanded.value.has(id)?expanded.value.delete(id):expanded.value.add(id)}
async function addCategory(parent:Cat){const name=prompt('新分类名称');if(!name?.trim())return;try{await api('/categories',send('POST',{name:name.trim(),parent_id:parent.id,sort_order:cats.value.filter(c=>c.parent_id===parent.id).length}));expanded.value.add(parent.id);await refresh()}catch(e){fail(e)}}
async function editCategory(){const c=currentCategory.value;if(!c)return;const name=prompt('修改分类名称',c.name);if(!name?.trim())return;try{await api('/categories/'+c.id,send('PUT',{name:name.trim(),parent_id:c.parent_id,sort_order:c.sort_order}));await refresh()}catch(e){fail(e)}}
async function moveCategory(id:number,target:number,position:string){try{await api('/categories/'+id+'/move',send('POST',{target_id:target,position}));if(position==='inside')expanded.value.add(target);await refresh()}catch(e){fail(e)}}
async function reorder(dir:number){const c=currentCategory.value;if(!c)return;const siblings=cats.value.filter(x=>x.parent_id===c.parent_id);const i=siblings.findIndex(x=>x.id===c.id), j=i+dir;if(j<0||j>=siblings.length)return;[siblings[i],siblings[j]]=[siblings[j],siblings[i]];try{for(let k=0;k<siblings.length;k++){const x=siblings[k];await api('/categories/'+x.id,send('PUT',{name:x.name,parent_id:x.parent_id,sort_order:k}))}await refresh()}catch(e){fail(e)}}
async function deleteCategory(){const c=currentCategory.value;if(!c)return;try{await api('/categories/'+c.id+(migrateTo.value?'?migrate_to='+migrateTo.value:'?confirm=true'),{method:'DELETE'});showDeleteCategory.value=false;selected.value=null;page.value='overview';await refresh()}catch(e){fail(e)}}
function blank(){return {title:'',summary:'',content_md:'',category_id:selected.value||roots.value[0]?.id,status:'not_started',difficulty:'beginner',is_favorite:false,source_url:'',tags:[]}}
function edit(n?:Note){if(!canLeave())return;draft.value=n?JSON.parse(JSON.stringify(n)):blank();draft.value.tagsText=draft.value.tags.join(', ');initialDraft.value=JSON.stringify(draft.value);page.value='edit'}
async function save(){try{const payload={...draft.value,tags:draft.value.tagsText.split(/[,，]/).map((s:string)=>s.trim()).filter(Boolean)};const n=await api('/notes'+(draft.value.id?'/'+draft.value.id:''),send(draft.value.id?'PUT':'POST',payload));dirty.value=false;await refresh();await openNote(n.id)}catch(e){fail(e)}}
async function openNote(id:number){if(!canLeave())return;try{current.value=await api('/notes/'+id+'?view=true');attachments.value=await api('/notes/'+id+'/attachments');page.value='read';await refresh()}catch(e){fail(e)}}
async function patchNote(n:Note,patch:any){try{const updated=await api('/notes/'+n.id,send('PUT',{...n,...patch}));if(current.value?.id===n.id)current.value=updated;await refresh()}catch(e){fail(e)}}
async function deleteNote(n:Note){if(!confirm(`确定删除「${n.title}」及其附件？`))return;try{await api('/notes/'+n.id,{method:'DELETE'});page.value='category';selected.value=n.category_id;await refresh()}catch(e){fail(e)}}
async function copyNote(n:Note){try{const x=await api('/notes',send('POST',{...n,title:n.title+'（副本）'}));await refresh();await openNote(x.id)}catch(e){fail(e)}}
async function filesSelected(e:Event){const files=Array.from((e.target as HTMLInputElement).files||[]).filter(f=>/\.md$/i.test(f.name));importItems.value=await Promise.all(files.map(async f=>({filename:f.webkitRelativePath||f.name,text:await f.text()})));try{importPreview.value=await api('/import/preview',send('POST',{items:importItems.value,default_category_id:selected.value}));showImport.value=true}catch(err){fail(err)};(e.target as HTMLInputElement).value=''}
async function doImport(){try{const r=await api('/import',send('POST',{items:importItems.value,default_category_id:selected.value,create_categories:createMissing.value,duplicate:duplicate.value}));showImport.value=false;await refresh();alert(`导入 ${r.imported} 篇，跳过 ${r.skipped} 篇。`)}catch(e){fail(e)}}
async function upload(e:Event){if(!current.value)return;const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;const fd=new FormData();fd.append('file',file);try{await api('/notes/'+current.value.id+'/attachments',{method:'POST',body:fd});attachments.value=await api('/notes/'+current.value.id+'/attachments')}catch(err){fail(err)}}
async function removeAttachment(id:number){if(!confirm('删除此附件？'))return;try{await api('/attachments/'+id,{method:'DELETE'});attachments.value=await api('/notes/'+current.value!.id+'/attachments')}catch(e){fail(e)}}
async function restore(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f||!confirm('恢复备份将覆盖当前知识库。系统会先保存一份当前数据的备份，继续吗？'))return;const fd=new FormData();fd.append('file',f);try{await api('/restore?confirm=true',{method:'POST',body:fd});page.value='overview';await refresh();alert('恢复完成。')}catch(err){fail(err)}}
function keydown(e:KeyboardEvent){if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(canLeave()){page.value='search';setTimeout(()=>document.querySelector<HTMLInputElement>('#global-search')?.focus(),0)}}}
function beforeUnload(e:BeforeUnloadEvent){if(page.value==='edit'&&dirty.value)e.preventDefault()}
onMounted(async()=>{window.addEventListener('keydown',keydown);window.addEventListener('beforeunload',beforeUnload);try{await refresh();roots.value.forEach(c=>expanded.value.add(c.id))}catch(e){fail(e)}})
onBeforeUnmount(()=>{window.removeEventListener('keydown',keydown);window.removeEventListener('beforeunload',beforeUnload)})
</script>
<template>
<div class="app-shell" :class="{'sidebar-hidden':!sidebar}" @click="copyMenu=null">
  <aside class="sidebar" v-show="sidebar">
    <div class="brand"><div class="brand-mark"><BookOpen :size="18"/></div><div><strong>StudyHub</strong><small>YOUR KNOWLEDGE SPACE</small></div></div>
    <div class="workspace-label">工作空间 <MoreHorizontal :size="16"/></div>
    <nav class="main-nav">
      <button :class="{active:page==='overview'}" @click="navigate('overview')"><LayoutDashboard :size="17"/> 学习概览</button>
      <button :class="{active:page==='favorites'}" @click="navigate('favorites')"><Star :size="17"/> 我的收藏</button>
      <button :class="{active:page==='recent'}" @click="navigate('recent')"><Clock3 :size="17"/> 最近学习</button>
    </nav>
    <div class="tree-heading"><span>知识分类</span><span>拖至上下排序 · 中间移动</span></div>
    <div class="tree-scroll"><TreeItem v-for="root in roots" :key="root.id" :node="root" :all="cats" :selected="page==='category'?selected:null" :expanded="expanded" :depth="0" @select="navigate('category',$event)" @toggle="toggle" @add="addCategory" @move="moveCategory"/></div>
    <div class="sidebar-bottom"><div class="avatar">S</div><div><strong>我的知识库</strong><small>保存在本地设备</small></div><span class="online-dot"></span></div>
  </aside>
  <main class="main">
    <header class="topbar"><button class="icon-btn sidebar-toggle" title="切换侧栏" @click="sidebar=!sidebar"><PanelLeft :size="18"/></button><div class="breadcrumb"><span>工作空间</span><ChevronRight :size="14"/><strong>{{pageTitle}}</strong></div><div class="top-actions"><div class="searchbox"><Search :size="16"/><input id="global-search" v-model="search" placeholder="搜索知识..." @keydown.enter="navigate('search')"><kbd>Ctrl K</kbd></div><label class="button subtle import-btn"><Upload :size="16"/> 导入文件<input hidden type="file" multiple accept=".md,text/markdown" @change="filesSelected"></label><label class="button subtle import-btn">导入文件夹<input hidden type="file" webkitdirectory multiple @change="filesSelected"></label><button class="button primary" @click="edit()"><Plus :size="16"/> 新建知识</button></div></header>
    <div v-if="error" class="toast">{{error}} <button @click="error=''">×</button></div>
    <div class="content" v-if="page==='overview'">
      <div class="welcome"><div><div class="eyebrow"><span class="spark">✦</span> 你的个人知识空间</div><h1>让每一次学习，<br><span>都有迹可循。</span></h1><p>记录、连接、掌握。把零散的知识，变成自己的体系。</p><button class="button primary" @click="edit()"><Plus :size="16"/> 创建一篇知识</button></div><div class="welcome-graphic"><div class="graphic-orbit orbit-one"></div><div class="graphic-orbit orbit-two"></div><div class="graphic-book"><BookOpen :size="42" stroke-width="1.25"/></div><span class="graphic-dot dot-one"></span><span class="graphic-dot dot-two"></span><span class="graphic-dot dot-three"></span></div></div>
      <div class="section-title"><div><h2>学习概览</h2><p>你的知识积累，一目了然</p></div><span class="muted">持续积累，每天进步一点点</span></div>
      <div class="stats-grid"><div class="stat-card"><div class="stat-icon blue"><FileText :size="18"/></div><span>知识文档</span><strong>{{stats.total}}</strong><small>篇知识已记录</small></div><div class="stat-card"><div class="stat-icon gray"><Clock3 :size="18"/></div><span>未开始</span><strong>{{stats.not_started}}</strong><small>等待探索</small></div><div class="stat-card"><div class="stat-icon amber"><BookOpen :size="18"/></div><span>学习中</span><strong>{{stats.learning}}</strong><small>正在积累</small></div><div class="stat-card"><div class="stat-icon green"><Check :size="18"/></div><span>已掌握</span><strong>{{stats.mastered}}</strong><small>收获的知识</small></div></div>
      <div class="section-title"><div><h2>探索知识分类</h2><p>从感兴趣的方向开始，构建你的知识体系</p></div></div>
      <div class="category-cards"><button v-for="(root,i) in roots" :key="root.id" class="category-card" @click="navigate('category',root)"><div class="category-icon" :class="'tone-'+i"><span>{{['✳','⌘','⌁'][i]}}</span></div><div><strong>{{root.name}}</strong><small>{{rootCount(root)}} 篇知识 · {{cats.filter(c=>c.parent_id===root.id).length}} 个分类</small></div><ArrowRight :size="17" class="card-arrow"/></button></div>
      <div class="activity-grid"><section class="panel"><div class="panel-head"><div><h2>最近阅读</h2><p>继续上次的学习</p></div><button class="text-link" @click="navigate('recent')">查看全部 <ArrowRight :size="14"/></button></div><div v-if="!recentNotes.length" class="empty-small"><Clock3 :size="22"/><span>还没有阅读记录</span><small>打开一篇知识，开始学习吧</small></div><button v-for="n in recentNotes" :key="n.id" class="activity-row" @click="openNote(n.id)"><FileText :size="16"/><span><strong>{{n.title}}</strong><small>{{n.category_path}}</small></span><small>{{date(n.last_viewed_at)}}</small></button></section><section class="panel"><div class="panel-head"><div><h2>最近更新</h2><p>回顾最近整理的内容</p></div></div><div v-if="!updatedNotes.length" class="empty-small"><FileText :size="22"/><span>还没有知识文档</span><small>创建第一篇笔记，开启知识积累</small></div><button v-for="n in updatedNotes" :key="n.id" class="activity-row" @click="openNote(n.id)"><FileText :size="16"/><span><strong>{{n.title}}</strong><small>{{n.category_path}}</small></span><small>{{date(n.updated_at)}}</small></button></section></div>
      <div class="data-actions"><a href="/api/export"><Download :size="15"/> 导出知识库</a><a href="/api/backup"><Database :size="15"/> 备份数据</a><label><Upload :size="15"/> 恢复备份<input hidden type="file" accept=".zip" @change="restore"></label></div>
    </div>
    <div class="content" v-else-if="['category','favorites','recent','search'].includes(page)">
      <div class="list-heading"><div><div class="eyebrow">{{page==='category'?'知识分类':'知识库'}}</div><h1>{{pageTitle}}</h1><p>{{page==='category'?currentCategory?.path:'在这里浏览你的知识文档'}}</p></div><div v-if="page==='category'" class="heading-actions"><button class="button subtle" @click="addCategory(currentCategory!)"><FolderPlus :size="16"/> 子分类</button><button class="icon-btn bordered" title="重命名" @click="editCategory"><Pencil :size="16"/></button><button class="icon-btn bordered" title="上移" @click="reorder(-1)">↑</button><button class="icon-btn bordered" title="下移" @click="reorder(1)">↓</button><a class="icon-btn bordered" title="导出分类" :href="'/api/export?category_id='+selected"><Download :size="16"/></a><button v-if="!currentCategory?.is_system" class="icon-btn bordered" title="删除分类" @click="migrateTo='';showDeleteCategory=true"><Trash2 :size="16"/></button></div></div>
      <div class="list-toolbar"><div class="list-count">知识文档 <span>{{notes.length}}</span></div><div class="filters"><select v-if="page==='search'" v-model="searchCategory" @change="loadNotes"><option value="">全部分类</option><option v-for="c in cats" :key="c.id" :value="String(c.id)">{{c.path}}</option></select><select v-if="page==='search'" v-model="searchTag" @change="loadNotes"><option value="">全部标签</option><option v-for="tag in availableTags" :key="tag" :value="tag">{{tag}}</option></select><label v-if="page==='category'" class="check-label"><input type="checkbox" v-model="recursive" @change="loadNotes"> 包含子分类</label><button class="icon-btn" :class="{chosen:!grid}" @click="grid=false"><List :size="17"/></button><button class="icon-btn" :class="{chosen:grid}" @click="grid=true"><Grid2X2 :size="16"/></button></div></div>
      <div v-if="!notes.length" class="empty"><div class="empty-icon"><FileText :size="25"/></div><h3>这里还没有知识</h3><p>创建或导入一篇文档，开始整理你的学习内容。</p><button class="button primary" @click="edit()"><Plus :size="16"/> 新建知识</button></div>
      <div v-else class="note-list" :class="{grid}"><div v-for="n in notes" :key="n.id" class="note-row" @click="openNote(n.id)"><div class="note-file"><FileText :size="18"/></div><div class="note-info"><strong>{{n.title}}</strong><p>{{n.summary || '暂无简介'}}</p><div class="note-meta"><span>{{n.category_path}}</span><span v-for="tag in n.tags" :key="tag" class="tag" @click.stop="search=tag;navigate('search')"># {{tag}}</span></div></div><span class="row-date">{{date(n.updated_at)}}</span><button class="icon-btn" @click.stop="patchNote(n,{is_favorite:!n.is_favorite})"><Star :size="17" :fill="n.is_favorite?'#e8ad42':'none'" :color="n.is_favorite?'#e8ad42':'currentColor'"/></button></div></div>
    </div>
    <div class="content editor-page" v-else-if="page==='edit'&&draft">
      <div class="editor-heading"><div><div class="eyebrow">知识编辑器</div><h1>{{draft.id?'编辑知识':'新建知识'}}</h1></div><div class="heading-actions"><button class="button subtle" @click="navigate(draft.id?'read':'overview')">取消</button><button class="button primary" @click="save"><Check :size="16"/> 保存文档</button></div></div>
      <div class="edit-fields" @input="dirty=JSON.stringify(draft)!==initialDraft" @change="dirty=true"><input class="title-input" v-model="draft.title" placeholder="输入知识标题..."><input v-model="draft.summary" placeholder="添加一句简介，概括这篇知识"><div class="field-row"><label>分类 <select v-model="draft.category_id"><option v-for="c in cats" :key="c.id" :value="c.id">{{c.path}}</option></select></label></div><div class="field-row"><label class="grow">标签 <input v-model="draft.tagsText" placeholder="多个标签用逗号分隔"></label><label class="grow">来源 <input v-model="draft.source_url" placeholder="https://..."></label></div></div>
      <MdEditor v-model="draft.content_md" language="zh-CN" class="markdown-editor" @onChange="dirty=true"/>
    </div>
    <div class="reader-layout" v-else-if="page==='read'&&current"><article class="reader" @contextmenu="selectionMenu"><button class="back-link" @click="navigate('category',cats.find(c=>c.id===current!.category_id))"><ArrowLeft :size="15"/> 返回分类</button><div class="reader-path">{{current.category_path}}</div><div class="reader-title"><h1>{{current.title}}</h1><button class="icon-btn bordered" @click="patchNote(current,{is_favorite:!current.is_favorite})"><Star :size="18" :fill="current.is_favorite?'#e8ad42':'none'" :color="current.is_favorite?'#e8ad42':'currentColor'"/></button></div><p class="reader-summary">{{current.summary}}</p><div class="reader-meta"><span>创建于 {{date(current.created_at)}}</span><span>更新于 {{date(current.updated_at)}}</span></div><div class="reader-tags"><span v-for="tag in current.tags" :key="tag" class="tag" @click="search=tag;navigate('search')"># {{tag}}</span></div><div class="reader-actions"><button @click="edit(current)"><Pencil :size="15"/> 编辑</button><button @click="copyNote(current)"><Copy :size="15"/> 复制文档</button><a :href="'/api/export?note_id='+current.id"><Download :size="15"/> 导出</a><a v-if="current.source_url && /^https?:\/\//i.test(current.source_url)" :href="current.source_url" target="_blank" rel="noopener noreferrer"><ExternalLink :size="15"/> 来源</a><button @click="deleteNote(current)"><Trash2 :size="15"/> 删除</button></div><MdPreview editor-id="reader-preview" :model-value="readerContent"/><div class="attachment-section"><h3><Paperclip :size="17"/> 附件</h3><div v-for="a in attachments" :key="a.id" class="attachment-row"><a :href="'/api/attachments/'+a.id" target="_blank">{{a.name}}</a><button @click="removeAttachment(a.id)">删除</button></div><label class="button subtle"><Plus :size="15"/> 添加附件<input hidden type="file" @change="upload"></label></div></article><aside class="toc"><strong>本页目录</strong><MdCatalog editor-id="reader-preview" :scroll-element="'html'"/></aside></div>
  </main>
  <div v-if="copyMenu" class="selection-menu" :style="{left:copyMenu.x+'px',top:copyMenu.y+'px'}" @mousedown.prevent @click.stop="copySelection">复制选中内容</div><div v-if="showDeleteCategory" class="modal-backdrop"><div class="modal"><div class="modal-head"><div><h2>删除分类</h2><p>删除「{{currentCategory?.name}}」前，可以将其直属文档及子分类迁移到其他分类。</p></div><button class="icon-btn" @click="showDeleteCategory=false"><X :size="19"/></button></div><label class="import-option">处理内容 <select v-model="migrateTo"><option value="">删除此分类及全部内容</option><option v-for="c in cats.filter(x=>x.id!==selected)" :key="c.id" :value="String(c.id)">迁移到 {{c.path}}</option></select></label><div class="modal-actions"><button class="button subtle" @click="showDeleteCategory=false">取消</button><button class="button primary" @click="deleteCategory">确认删除</button></div></div></div><div v-if="showImport" class="modal-backdrop"><div class="modal"><div class="modal-head"><div><h2>导入 Markdown</h2><p>确认文件与分类后导入知识库</p></div><button class="icon-btn" @click="showImport=false"><X :size="19"/></button></div><div class="import-list"><div v-for="item in importPreview" :key="item.filename"><FileText :size="17"/><span><strong>{{item.title}}</strong><small>{{item.category || '使用当前分类'}} · {{item.filename}}</small></span><em v-if="item.existing_id">ID 已存在</em><em v-else-if="!item.category_exists">分类不存在</em></div></div><label class="check-label"><input type="checkbox" v-model="createMissing"> 自动创建不存在的子分类</label><label class="import-option">遇到已有文档 ID <select v-model="duplicate"><option value="skip">跳过</option><option value="update">更新</option></select></label><div class="modal-actions"><button class="button subtle" @click="showImport=false">取消</button><button class="button primary" @click="doImport">导入 {{importItems.length}} 个文件</button></div></div></div>
</div>
</template>
